(6435145, 955295, 128751, '<td valign="top">Whoa! We took a picture of the same tree, that is bizarre.</td>', 'Whoa! We took a picture of the same tree, that is bizarre.', '2011-06-06 01:05:43.000000', NULL, 1),
(6435167, 955465, 70484, '<td valign="top">I really like this photo. However, the horizon isn''t straight and that is kinda bothering me. The right side is higher than the left side.</td>', 'I really like this photo. However, the horizon isn''t straight and that is kinda bothering me. The right side is higher than the left side.', '2011-06-06 01:11:48.000000', NULL, 1),
(6435184, 955170, 130694, '<td valign="top">This just doesn''t seem very minimal. Nice shot tho</td>', 'This just doesn''t seem very minimal. Nice shot tho', '2011-06-06 01:17:59.000000', NULL, 1),
(6435185, 955642, 130694, '<td valign="top">Not very minimal in my opinion, but I love waterfalls and its a great shot otherwise.</td>', 'Not very minimal in my opinion, but I love waterfalls and its a great shot otherwise.', '2011-06-06 01:18:43.000000', NULL, 1),
(6435193, 955607, 130694, '<td valign="top">This just doesent seem to me to be minimal in nature.</td>', 'This just doesent seem to me to be minimal in nature.', '2011-06-06 01:20:24.000000', NULL, 1),
(6435198, 955571, 96751, '<td valign="top">Gorgeous.</td>', 'Gorgeous.', '2011-06-06 01:21:54.000000', NULL, 1),
(6435199, 955228, 130694, '<td valign="top">This image bothers my eyes to no end. Its because its upside down, I ams sure you did that on purpose.. tho not sure why (other then maybe to make the refection of the person the focus?) Flipping it around its a great shot.</td>', 'This image bothers my eyes to no end. Its because its upside down, I ams sure you did that on purpose.. tho not sure why (other then maybe to make the refection of the person the focus?) Flipping it around its a great shot.', '2011-06-06 01:21:56.000000', NULL, 1),
(6435202, 954861, 96751, '<td valign="top">Non-tradition, and truly beautiful.  Can''t decide if the grain helps or hinders.  But lovely tones.</td>', 'Non-tradition, and truly beautiful.  Can''t decide if the grain helps or hinders.  But lovely tones.', '2011-06-06 01:22:40.000000', NULL, 1),
(6435206, 955617, 96751, '<td valign="top">Splendid, but not my idea of minimalist.</td>', 'Splendid, but not my idea of minimalist.', '2011-06-06 01:23:33.000000', NULL, 1),
(6435207, 955533, 130694, '<td valign="top">I really wish this image wasnt cropped so much (or at least the overall image size larger after the crop)</td>', 'I really wish this image wasnt cropped so much (or at least the overall image size larger after the crop)', '2011-06-06 01:23:33.000000', NULL, 1),
(6435210, 954843, 96751, '<td valign="top">Beautiful.  Excellent reflection.</td>', 'Beautiful.  Excellent reflection.', '2011-06-06 01:23:48.000000', NULL, 1),
(6435213, 955465, 96751, '<td valign="top">Looks like one of those baby turtles heading for the sea.<br/> <br/>I love the sky/ocean, and I love the beach/boat.  But somehow they don''t go together.</td>', 'Looks like one of those baby turtles heading for the sea. I love the sky/ocean, and I love the beach/boat.  But somehow they don''t go together.', '2011-06-06 01:24:38.000000', NULL, 1),
(6435214, 955292, 96751, '<td valign="top">Very impressive.  Looks like a model.</td>', 'Very impressive.  Looks like a model.', '2011-06-06 01:24:58.000000', NULL, 1),
(6435215, 955146, 114285, '<td valign="top">Very lovely, I bet this is your''s Margaret, those warm tones, are warming me up.</td>', 'Very lovely, I bet this is your''s Margaret, those warm tones, are warming me up.', '2011-06-06 01:25:05.000000', NULL, 1),
(6435217, 955428, 96751, '<td valign="top">What a fabulous tree.  I find it a tish on the dark side, but otherwise, a splendid entry.</td>', 'What a fabulous tree.  I find it a tish on the dark side, but otherwise, a splendid entry.', '2011-06-06 01:25:28.000000', NULL, 1),
(6435218, 955531, 130694, '<td valign="top">I love the picture, just dont think it fits the minimalist aspect for me personally.</td>', 'I love the picture, just dont think it fits the minimalist aspect for me personally.', '2011-06-06 01:25:39.000000', NULL, 1),
(6435219, 954572, 114285, '<td valign="top">The sun rays are out of this world, this has to be on the front page.</td>', 'The sun rays are out of this world, this has to be on the front page.', '2011-06-06 01:25:40.000000', NULL, 1),
(6435221, 955529, 96751, '<td valign="top">I love this, although it is neither a landscape nor minimal to me.  Gorgeous light.</td>', 'I love this, although it is neither a landscape nor minimal to me.  Gorgeous light.', '2011-06-06 01:25:52.000000', NULL, 1),
(6435222, 955684, 114285, '<td valign="top">I can see why, it''s gorgeous.</td>', 'I can see why, it''s gorgeous.', '2011-06-06 01:26:03.000000', NULL, 1),
(6435225, 955027, 96751, '<td valign="top">The idea is in the right direction, and it is both a lovely example of minimalism and negative space.  For me, though, the lighting is a bit flat overall, with everything receiving the same tonal value.</td>', 'The idea is in the right direction, and it is both a lovely example of minimalism and negative space.  For me, though, the lighting is a bit flat overall, with everything receiving the same tonal value.', '2011-06-06 01:27:00.000000', NULL, 1),
(6435227, 954836, 96751, '<td valign="top">Oh, how marvelous.  Those stars are divine, as are the rich tones.</td>', 'Oh, how marvelous.  Those stars are divine, as are the rich tones.', '2011-06-06 01:27:21.000000', NULL, 1),
(6435231, 954859, 96751, '<td valign="top">Beautiful sky, although I''m not getting the extremely narrow crop.</td>', 'Beautiful sky, although I''m not getting the extremely narrow crop.', '2011-06-06 01:28:09.000000', NULL, 1),
(6435233, 955519, 96751, '<td valign="top">Love that blur and the standout colors.</td>', 'Love that blur and the standout colors.', '2011-06-06 01:28:25.000000', NULL, 1),
(6435234, 955446, 96751, '<td valign="top">Magnificent.  Our poppy season was bust this year.  How very fortunate to have found this vista.  And that cloud!</td>', 'Magnificent.  Our poppy season was bust this year.  How very fortunate to have found this vista.  And that cloud!', '2011-06-06 01:29:05.000000', NULL, 1),
(6435236, 955146, 96751, '<td valign="top">Gorgeous!</td>', 'Gorgeous!', '2011-06-06 01:29:43.000000', NULL, 1),
(6435237, 955425, 96751, '<td valign="top">Beautiful lines and reflections in the sky and water, and a very defiant foam line.  But the sand is dark and untextured.</td>', 'Beautiful lines and reflections in the sky and water, and a very defiant foam line.  But the sand is dark and untextured.', '2011-06-06 01:31:04.000000', NULL, 1),
(6435238, 955254, 96751, '<td valign="top">What a curious and oddly appealing combination.  The small and blurry, and the distant and imposing.</td>', 'What a curious and oddly appealing combination.  The small and blurry, and the distant and imposing.', '2011-06-06 01:31:37.000000', NULL, 1),
(6435240, 955348, 96751, '<td valign="top">LOVE that blue!!!!</td>', 'LOVE that blue!!!!', '2011-06-06 01:32:18.000000', NULL, 1),
(6435243, 955673, 96751, '<td valign="top">I love the delicacy of the edge with the grasses, and the boldness of all that white, negative space.  But I''m going through a borderless phase, so I really hate the way that border interrupts my view.</td>', 'I love the delicacy of the edge with the grasses, and the boldness of all that white, negative space.  But I''m going through a borderless phase, so I really hate the way that border interrupts my view.', '2011-06-06 01:33:36.000000', NULL, 1),
(6435247, 954976, 96751, '<td valign="top">Vistas like this make me feel like I''m looking into eternity.</td>', 'Vistas like this make me feel like I''m looking into eternity.', '2011-06-06 01:34:13.000000', NULL, 1),
(6435251, 955383, 96751, '<td valign="top">This reminds me a lot of mine.  Fabulous sky, although there is a lot of haloing around the tree.</td>', 'This reminds me a lot of mine.  Fabulous sky, although there is a lot of haloing around the tree.', '2011-06-06 01:35:11.000000', NULL, 1),
(6435254, 955664, 96751, '<td valign="top">There is a real "scorched earth" feel about this image.  Very intriguing.</td>', 'There is a real "scorched earth" feel about this image.  Very intriguing.', '2011-06-06 01:35:49.000000', NULL, 1),
(6435255, 955684, 96751, '<td valign="top">I can see why.  Lovely.</td>', 'I can see why.  Lovely.', '2011-06-06 01:36:00.000000', NULL, 1),
(6435258, 955632, 96751, '<td valign="top">Killer.  This should do very well.</td>', 'Killer.  This should do very well.', '2011-06-06 01:36:13.000000', NULL, 1),
(6435259, 955406, 96751, '<td valign="top">Fits the challenge perfectly, but I feel it is a bit "thick", tonally.  I can see some variation wanting to come out and play.</td>', 'Fits the challenge perfectly, but I feel it is a bit "thick", tonally.  I can see some variation wanting to come out and play.', '2011-06-06 01:36:52.000000', NULL, 1),
(6435263, 955428, 130694, '<td valign="top">This is my favorite, I had given it a 9, but it just keeps bringing me back. So I had to up it to a 10. Great shot.</td>', 'This is my favorite, I had given it a 9, but it just keeps bringing me back. So I had to up it to a 10. Great shot.', '2011-06-06 01:37:15.000000', NULL, 1),
(6435265, 955656, 96751, '<td valign="top">Lovely.  It looks like either the tree is blowing out the fluff clouds, or sucking them in.</td>', 'Lovely.  It looks like either the tree is blowing out the fluff clouds, or sucking them in.', '2011-06-06 01:37:53.000000', NULL, 1),
