(6435288, 955643, 126371, '<td valign="top">Sunstars sure do add a lot to any scene!Great exposure and contrast. I was wondering, is the left side of the image a bit empty?</td>', 'Sunstars sure do add a lot to any scene!Great exposure and contrast. I was wondering, is the left side of the image a bit empty?', '2011-06-06 01:43:51.000000', NULL, 1),
(6435290, 955617, 54645, '<td valign="top">Beautiful. Too sharp, but lovely nonetheless.</td>', 'Beautiful. Too sharp, but lovely nonetheless.', '2011-06-06 01:44:34.000000', NULL, 1),
