(6435299, 955683, 54645, '<td valign="top">Brave border. I like the image.</td>', 'Brave border. I like the image.', '2011-06-06 01:49:09.000000', NULL, 1),
(6435303, 954920, 54645, '<td valign="top">Powerful. &lt;From Abby...the sky is scary creepy. The palm trees are nice. The bottom clouds looks like a wave, as if the ocean is in the background. I kind of like it. Good job on the rest, the sky is scary.&gt;</td>', 'Powerful. <From Abby...the sky is scary creepy. The palm trees are nice. The bottom clouds looks like a wave, as if the ocean is in the background. I kind of like it. Good job on the rest, the sky is scary.>', '2011-06-06 01:51:47.000000', NULL, 1),
