(6435382, 955683, 97225, '<td valign="top">Lovely.</td>', 'Lovely.', '2011-06-06 03:40:49.000000', NULL, 1),
(6435386, 955456, 97225, '<td valign="top">I Like the image but it doesn''t come across as a minimalist landscape.</td>', 'I Like the image but it doesn''t come across as a minimalist landscape.', '2011-06-06 03:50:51.000000', NULL, 1),
(6435388, 955607, 97225, '<td valign="top">Lovely image but it isn''t my idea of minimalist.</td>', 'Lovely image but it isn''t my idea of minimalist.', '2011-06-06 03:52:05.000000', NULL, 1),
(6435389, 954949, 97225, '<td valign="top">Beautiful serene image, but I don''t really think it is minimalist.</td>', 'Beautiful serene image, but I don''t really think it is minimalist.', '2011-06-06 03:54:40.000000', NULL, 1),
