(6435638, 955673, 43774, '<td valign="top">Nice, I really like it, especially the dark sky.</td>', 'Nice, I really like it, especially the dark sky.', '2011-06-06 09:40:05.000000', NULL, 1),
(6435639, 955597, 43774, '<td valign="top">Really nice, especially the shadow.</td>', 'Really nice, especially the shadow.', '2011-06-06 09:40:28.000000', NULL, 1),
