(6435998, 955571, 109387, '<td valign="top">Etretat? Maybe someone could tell you this is not minimalist, but I think it is, so an 8 for you ^_^</td>', 'Etretat? Maybe someone could tell you this is not minimalist, but I think it is, so an 8 for you ^_^', '2011-06-06 16:51:50.000000', NULL, 1),
(6436000, 955666, 109387, '<td valign="top">The light and the contrast are too strong. And I think the image needed a little more sky.</td>', 'The light and the contrast are too strong. And I think the image needed a little more sky.', '2011-06-06 16:54:01.000000', NULL, 1),
(6436008, 955602, 113156, '<td valign="top">Wonderfully done, the picture exubes harmony, I could sit quite some time here.</td>', 'Wonderfully done, the picture exubes harmony, I could sit quite some time here.', '2011-06-06 16:55:51.000000', NULL, 1),
(6436009, 955653, 109387, '<td valign="top">Too blacks and the horizon to be fixed (I mean the distorsion) but in any case a very good image  :)</td>', 'Too blacks and the horizon to be fixed (I mean the distorsion) but in any case a very good image  :)', '2011-06-06 16:56:05.000000', NULL, 1),
