INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6436037, 955676, 113156, '<td valign="top">Got to be one of my favorites in this challenge, love the tonality of the grasses and the path leading through.</td>', 'Got to be one of my favorites in this challenge, love the tonality of the grasses and the path leading through.', '2011-06-06 17:05:18.000000', NULL, 1),
(6436056, 954864, 109387, '<td valign="top">It''s a very minimal and interesting landscape, but you should have fixed the chromatic aberration between the sand and the sky</td>', 'It''s a very minimal and interesting landscape, but you should have fixed the chromatic aberration between the sand and the sky', '2011-06-06 17:13:48.000000', NULL, 1),
(6436131, 954295, 132996, '<td valign="top">Perfect! I love the vignette also!</td>', 'Perfect! I love the vignette also!', '2011-06-06 18:07:28.000000', NULL, 1),
(6436136, 955496, 126371, '<td valign="top">WOOOOOW! BEAUTIFUL lighting, contrast, colors, etc.. I''ve been to Horseshoe Park, but this is an excellent view of it. I just had to sit here enjoying every ray, river bend, and aspen. I hope this does well!</td>', 'WOOOOOW! BEAUTIFUL lighting, contrast, colors, etc.. I''ve been to Horseshoe Park, but this is an excellent view of it. I just had to sit here enjoying every ray, river bend, and aspen. I hope this does well!', '2011-06-06 18:13:32.000000', NULL, 1),
(6436179, 955571, 108069, '<td valign="top">Stunning shot. Great tones, interesting composition. Graceful motion. Beauty.</td>', 'Stunning shot. Great tones, interesting composition. Graceful motion. Beauty.', '2011-06-06 19:28:05.000000', NULL, 1),
(6436180, 955446, 108069, '<td valign="top">Wow. Beautiful shot. Dynamic and vibrant colors. Well composed with the topography and cloud as well.</td>', 'Wow. Beautiful shot. Dynamic and vibrant colors. Well composed with the topography and cloud as well.', '2011-06-06 19:30:31.000000', NULL, 1),
(6436181, 955490, 108069, '<td valign="top">Beautiful. So delicate. Amazing to see birds as well. Nice tones, subtle, simple beauty.</td>', 'Beautiful. So delicate. Amazing to see birds as well. Nice tones, subtle, simple beauty.', '2011-06-06 19:32:18.000000', NULL, 1),
(6436187, 955682, 108069, '<td valign="top">I really like this. Lovely light mood, nice hands-off processing. Nicely cropped, love the bit of noise. Nice detail and tones in a minimal scene. Great job.</td>', 'I really like this. Lovely light mood, nice hands-off processing. Nicely cropped, love the bit of noise. Nice detail and tones in a minimal scene. Great job.', '2011-06-06 19:41:59.000000', NULL, 1),
(6436192, 954935, 108069, '<td valign="top">Very nice leading line into the distance. A good shot that I think could be helped by leveling that horizon and working a bit to tone down the contrast. There''s something to it that just seems a little harsh, possibly the contrast between the green seaweed and the sand. A nicely spotted scene that if delivered slightly differently would be even better.</td>', 'Very nice leading line into the distance. A good shot that I think could be helped by leveling that horizon and working a bit to tone down the contrast. There''s something to it that just seems a little harsh, possibly the contrast between the green seaweed and the sand. A nicely spotted scene that if delivered slightly differently would be even better.', '2011-06-06 19:46:01.000000', NULL, 1),
(6436193, 955579, 108069, '<td valign="top">Stunner of a shot. So crisp, beautiful light, perfectly composed, lovely subtle colors and tones. Excellent.</td>', 'Stunner of a shot. So crisp, beautiful light, perfectly composed, lovely subtle colors and tones. Excellent.', '2011-06-06 19:46:53.000000', NULL, 1),
(6436194, 955597, 7810, '<td valign="top">very good eye well composed</td>', 'very good eye well composed', '2011-06-06 19:48:22.000000', NULL, 1),
