INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6437050, 955254, 118154, '<td valign="top">Has a cartoony feel to it.</td>', 'Has a cartoony feel to it.', '2011-06-07 14:02:32.000000', NULL, 1),
(6437051, 955268, 118154, '<td valign="top">Nicely done.</td>', 'Nicely done.', '2011-06-07 14:02:49.000000', NULL, 1),
(6437052, 955643, 118154, '<td valign="top">One of many,this one better than others.</td>', 'One of many,this one better than others.', '2011-06-07 14:03:31.000000', NULL, 1),
(6437053, 955446, 118154, '<td valign="top">Nice !</td>', 'Nice !', '2011-06-07 14:04:25.000000', NULL, 1),
(6437054, 955428, 118154, '<td valign="top">That,s a brilliant tree,good shot.</td>', 'That,s a brilliant tree,good shot.', '2011-06-07 14:05:01.000000', NULL, 1),
(6437055, 955465, 118154, '<td valign="top">I like.</td>', 'I like.', '2011-06-07 14:05:25.000000', NULL, 1),
(6437165, 955146, 19825, '<td valign="top">I really don''t know if this is minimal or not, but it is a beautiful shot so I guess I don''t care.</td>', 'I really don''t know if this is minimal or not, but it is a beautiful shot so I guess I don''t care.', '2011-06-07 17:05:37.000000', NULL, 1),
(6437172, 955541, 10785, '<td valign="top">The foreground is very well exposed (but just a little over-sharp) and I like how it leads you up to the top left corner of the photo. Unfortunately that is where the problems begin. The blowout kind of kills the color of the barn and there is significant digital banding artifacts in the sky.</td>', 'The foreground is very well exposed (but just a little over-sharp) and I like how it leads you up to the top left corner of the photo. Unfortunately that is where the problems begin. The blowout kind of kills the color of the barn and there is significant digital banding artifacts in the sky.', '2011-06-07 17:16:44.000000', NULL, 1),
(6437173, 955682, 10785, '<td valign="top">The tones are very light, kind of high key, but not really. I would rather see more shadows in your exposure. The sky has some significant amounts of noise which does not appear to be used to add texture or dimension to the photo.</td>', 'The tones are very light, kind of high key, but not really. I would rather see more shadows in your exposure. The sky has some significant amounts of noise which does not appear to be used to add texture or dimension to the photo.', '2011-06-07 17:18:25.000000', NULL, 1),
(6437176, 955667, 10785, '<td valign="top">All the blue makes it very cold which is neither good nor bad. I love the shape and reflection shown. Triangle = Strength.</td>', 'All the blue makes it very cold which is neither good nor bad. I love the shape and reflection shown. Triangle = Strength.', '2011-06-07 17:19:21.000000', NULL, 1),
(6437177, 955563, 10785, '<td valign="top">This is cool. You took a small space and made it a minimal landscape. There is not much richness in the light captured here and there is a reddish cast on the photo.I do like the made mountain.<br/> <br/>It would have been cool if the mountain were capped with snow and the rest had melted... but I assure you that I am not voting on what is not in the photo.</td>', 'This is cool. You took a small space and made it a minimal landscape. There is not much richness in the light captured here and there is a reddish cast on the photo.I do like the made mountain. It would have been cool if the mountain were capped with snow and the rest had melted... but I assure you that I am not voting on what is not in the photo.', '2011-06-07 17:21:44.000000', NULL, 1),
(6437179, 955643, 10785, '<td valign="top">I really like the chosen point of view for this shot. It adds strength.</td>', 'I really like the chosen point of view for this shot. It adds strength.', '2011-06-07 17:23:42.000000', NULL, 1),
(6437183, 955665, 10785, '<td valign="top">Great exposure and quite an uncluttered look to this. The shapes, the lines, the texture, the rich color all add to the quality of the shot. I am assuming this is two exposures or a well merged HDR.</td>', 'Great exposure and quite an uncluttered look to this. The shapes, the lines, the texture, the rich color all add to the quality of the shot. I am assuming this is two exposures or a well merged HDR.', '2011-06-07 17:26:08.000000', NULL, 1),
(6437187, 955374, 10785, '<td valign="top">The colors are super rich. I like what you have done here. The landscape is shown minimally and you have captured the vast expanse of the sky. I also like the way you have lined the subject up with the light. I think the silhouette is not quite sharp enough and when I was working on my image, I noticed that applying too much noise reduction to the entire image reduced the sharpness considerably. I am guessing that might be a similar problem here.</td>', 'The colors are super rich. I like what you have done here. The landscape is shown minimally and you have captured the vast expanse of the sky. I also like the way you have lined the subject up with the light. I think the silhouette is not quite sharp enough and when I was working on my image, I noticed that applying too much noise reduction to the entire image reduced the sharpness considerably. I am guessing that might be a similar problem here.', '2011-06-07 17:30:08.000000', NULL, 1),
(6437199, 955006, 68947, '<td valign="top">LOL...now there''s a way around the entire conflict on what constitutes a "Minimal Landscape"....don''t include ANY land! ;)  Made me chuckle.</td>', 'LOL...now there''s a way around the entire conflict on what constitutes a "Minimal Landscape"....don''t include ANY land! ;)  Made me chuckle.', '2011-06-07 17:42:31.000000', NULL, 1),
(6437200, 955642, 68947, '<td valign="top">Beautiful scene and nicely shot.  Just not sure whether it fits "minimal landscape" or not??? (not scoring)</td>', 'Beautiful scene and nicely shot.  Just not sure whether it fits "minimal landscape" or not??? (not scoring)', '2011-06-07 17:43:31.000000', NULL, 1),
(6437201, 955148, 68947, '<td valign="top">Yup...not much land there. :)  love the b&amp;w and the sort of vignette and grain feel.  (not scoring)</td>', 'Yup...not much land there. :)  love the b&w and the sort of vignette and grain feel.  (not scoring)', '2011-06-07 17:44:09.000000', NULL, 1),
(6437202, 955520, 68947, '<td valign="top">Beautiful!  I''d call this minimal landscape.  Hope everyone else does too.</td>', 'Beautiful!  I''d call this minimal landscape.  Hope everyone else does too.', '2011-06-07 17:44:41.000000', NULL, 1),
(6437203, 954976, 68947, '<td valign="top">Very pretty.  Certainly minimal in land. :)  (not scoring)</td>', 'Very pretty.  Certainly minimal in land. :)  (not scoring)', '2011-06-07 17:45:30.000000', NULL, 1),
(6437204, 955684, 68947, '<td valign="top">Beautiful tones and scape! (not scoring)</td>', 'Beautiful tones and scape! (not scoring)', '2011-06-07 17:45:57.000000', NULL, 1),
(6437205, 954836, 68947, '<td valign="top">very pretty, perhaps, too darkened and oversaturated but, it certainly makes for a lovely, almost abstract scene (not scoring)</td>', 'very pretty, perhaps, too darkened and oversaturated but, it certainly makes for a lovely, almost abstract scene (not scoring)', '2011-06-07 17:46:57.000000', NULL, 1),
