(6437271, 955612, 68947, '<td valign="top">Lonely but, very beautiful! :)</td>', 'Lonely but, very beautiful! :)', '2011-06-07 18:19:07.000000', NULL, 1),
(6437273, 954861, 68947, '<td valign="top">Uhhh...yup....that''s Switzerland....glad you didn''t say Iceland or I would have had to say DNMC! LOL ;) (not scoring)</td>', 'Uhhh...yup....that''s Switzerland....glad you didn''t say Iceland or I would have had to say DNMC! LOL ;) (not scoring)', '2011-06-07 18:20:14.000000', NULL, 1),
(6437274, 955383, 68947, '<td valign="top">The sky is a killer view! :)</td>', 'The sky is a killer view! :)', '2011-06-07 18:20:35.000000', NULL, 1),
(6437310, 955428, 18073, '<td valign="top">Congrats on a tremendous image, love the subdued tones here and that tree is straight off a Tim Burton movie - fantastic.  Hope this does well for you, my fave of this challenge.</td>', 'Congrats on a tremendous image, love the subdued tones here and that tree is straight off a Tim Burton movie - fantastic.  Hope this does well for you, my fave of this challenge.', '2011-06-07 18:47:29.000000', NULL, 1),
(6437345, 955584, 132996, '<td valign="top">Gorgeous. Despite the fact that the rocks are a mere 10% of this image, it''s all I look at. Great use of negative space to make this minimalist!</td>', 'Gorgeous. Despite the fact that the rocks are a mere 10% of this image, it''s all I look at. Great use of negative space to make this minimalist!', '2011-06-07 19:09:48.000000', NULL, 1),
(6437346, 955466, 132996, '<td valign="top">Good image; however, I think it would look even better if you filled the frame with the lines of corn. Nice shallow depth of field, though. :)</td>', 'Good image; however, I think it would look even better if you filled the frame with the lines of corn. Nice shallow depth of field, though. :)', '2011-06-07 19:10:35.000000', NULL, 1),
(6437347, 955170, 132996, '<td valign="top">Gorgeous. There aren''t any true blacks in this image, but the white snow pops so much. I think it would be ruined with the blacks. The grays really make this a stunning image!</td>', 'Gorgeous. There aren''t any true blacks in this image, but the white snow pops so much. I think it would be ruined with the blacks. The grays really make this a stunning image!', '2011-06-07 19:11:20.000000', NULL, 1),
(6437350, 955643, 132996, '<td valign="top">My first impression was that this was a person jumping! The shadow and embankment make it look like legs! Excellent illusion. :)</td>', 'My first impression was that this was a person jumping! The shadow and embankment make it look like legs! Excellent illusion. :)', '2011-06-07 19:12:12.000000', NULL, 1),
(6437351, 954836, 132996, '<td valign="top">Very minimalist with such subtle details (like the stars). Great shot. :)</td>', 'Very minimalist with such subtle details (like the stars). Great shot. :)', '2011-06-07 19:12:55.000000', NULL, 1),
(6437352, 955428, 132996, '<td valign="top">That tree has such a personality! Nice idea to focus on it.</td>', 'That tree has such a personality! Nice idea to focus on it.', '2011-06-07 19:13:47.000000', NULL, 1),
