(6442016, 955519, 104009, '<td valign="top">breath taking.  9</td>', 'breath taking.  9', '2011-06-12 18:26:33.000000', NULL, 1),
(6442025, 955496, 104230, '<td valign="top">Lovely capture of receding hills and ridges.  The top half meets the challenge topic and a panoramic view of just that would be gorgeous IMO, but I find the lower half too busy and my eye keeps getting drawn there instead.</td>', 'Lovely capture of receding hills and ridges.  The top half meets the challenge topic and a panoramic view of just that would be gorgeous IMO, but I find the lower half too busy and my eye keeps getting drawn there instead.', '2011-06-12 18:34:14.000000', NULL, 1),
(6442111, 955519, 11769, '<td valign="top">That''s quite a title, I love it. Beautiful gutsy piece.</td>', 'That''s quite a title, I love it. Beautiful gutsy piece.', '2011-06-12 20:48:39.000000', NULL, 1),
(6442112, 955632, 11769, '<td valign="top">With a minimalist title to boot.</td>', 'With a minimalist title to boot.', '2011-06-12 20:48:45.000000', NULL, 1),
(6442117, 955490, 110967, '<td valign="top">I love the aged feel and the centered focal point - 8</td>', 'I love the aged feel and the centered focal point - 8', '2011-06-12 21:05:02.000000', NULL, 1),
(6442119, 955148, 110967, '<td valign="top">perfect shot the for the challenge - 8</td>', 'perfect shot the for the challenge - 8', '2011-06-12 21:06:56.000000', NULL, 1),
(6442127, 955490, 114225, '<td valign="top">I really like your center composition. I don''t think I would have tried that here, and I would have come out with an inferior image.</td>', 'I really like your center composition. I don''t think I would have tried that here, and I would have come out with an inferior image.', '2011-06-12 21:12:10.000000', NULL, 1),
(6442129, 955445, 114225, '<td valign="top">HDR feels a bit opposite of minimalism to me. But overall your intent was right so I will ignore that. Very nice photo.</td>', 'HDR feels a bit opposite of minimalism to me. But overall your intent was right so I will ignore that. Very nice photo.', '2011-06-12 21:13:22.000000', NULL, 1),
(6442131, 955571, 114225, '<td valign="top">Wonderful example of what this challenge is supposed to be about.</td>', 'Wonderful example of what this challenge is supposed to be about.', '2011-06-12 21:16:14.000000', NULL, 1),
(6442134, 955374, 114225, '<td valign="top">In my view, this good example of a minimal landscape could have been even better if the tree was in sharp focus (at least it looks a little blurry to my eyes).</td>', 'In my view, this good example of a minimal landscape could have been even better if the tree was in sharp focus (at least it looks a little blurry to my eyes).', '2011-06-12 21:17:29.000000', NULL, 1),
(6442135, 954864, 54645, '<td valign="top">Tremendous texture.</td>', 'Tremendous texture.', '2011-06-12 21:17:32.000000', NULL, 1),
(6442141, 954903, 54645, '<td valign="top">Golden California</td>', 'Golden California', '2011-06-12 21:24:22.000000', NULL, 1),
