(6442192, 955617, 18367, '<td valign="top">This is a truly wonderful photo of a beautiful barn.  I do hope this is located close to where I live as I would love to take a photo of this one.  Great job... good luck in the challenge.</td>', 'This is a truly wonderful photo of a beautiful barn.  I do hope this is located close to where I live as I would love to take a photo of this one.  Great job... good luck in the challenge.', '2011-06-12 22:21:12.000000', NULL, 1),
(6442193, 954864, 73250, '<td valign="top">One of my favorites of the challenge, but I find the frame to be rather distracting.</td>', 'One of my favorites of the challenge, but I find the frame to be rather distracting.', '2011-06-12 22:21:42.000000', NULL, 1),
(6442204, 955389, 76335, '<td valign="top">Figure is a bit hard to see...</td>', 'Figure is a bit hard to see...', '2011-06-12 22:38:56.000000', NULL, 1),
(6442207, 955612, 76335, '<td valign="top">Sky is overworked...</td>', 'Sky is overworked...', '2011-06-12 22:40:02.000000', NULL, 1),
(6442208, 955602, 76335, '<td valign="top">Nice gritty layers...</td>', 'Nice gritty layers...', '2011-06-12 22:40:19.000000', NULL, 1),
(6442210, 955648, 76335, '<td valign="top">Almost feels like Kodachrome.</td>', 'Almost feels like Kodachrome.', '2011-06-12 22:41:03.000000', NULL, 1),
(6442212, 954295, 76335, '<td valign="top">Very Benimalist. The gull and the dark line of horizon, both at the extreme edges of the frame, make this feel huge -- and especially empty. Great!</td>', 'Very Benimalist. The gull and the dark line of horizon, both at the extreme edges of the frame, make this feel huge -- and especially empty. Great!', '2011-06-12 22:43:58.000000', NULL, 1),
(6442213, 955084, 76335, '<td valign="top">I love what this suggests.</td>', 'I love what this suggests.', '2011-06-12 22:44:14.000000', NULL, 1),
(6442217, 955562, 76335, '<td valign="top">I love pylons. That little poof of cloud is essential.</td>', 'I love pylons. That little poof of cloud is essential.', '2011-06-12 22:46:53.000000', NULL, 1),
(6442218, 954627, 76335, '<td valign="top">So in your face, so monolithic, so nothing of a tree... I have to laugh. It''s great.</td>', 'So in your face, so monolithic, so nothing of a tree... I have to laugh. It''s great.', '2011-06-12 22:47:36.000000', NULL, 1),
(6442222, 955349, 76335, '<td valign="top">Minimal in intrigue. I can dig it.</td>', 'Minimal in intrigue. I can dig it.', '2011-06-12 22:49:19.000000', NULL, 1),
(6442226, 955446, 76335, '<td valign="top">A heavy cloud over a red field. Surreal...</td>', 'A heavy cloud over a red field. Surreal...', '2011-06-12 22:52:16.000000', NULL, 1),
(6442231, 955277, 76335, '<td valign="top">Looks like a Pacific atoll or some such. Will be curious to know where this is.</td>', 'Looks like a Pacific atoll or some such. Will be curious to know where this is.', '2011-06-12 22:55:28.000000', NULL, 1),
(6442232, 955671, 76335, '<td valign="top">Excellent natural framing here...</td>', 'Excellent natural framing here...', '2011-06-12 22:56:06.000000', NULL, 1),
(6442233, 954836, 76335, '<td valign="top">I feel so mortal looking at this...</td>', 'I feel so mortal looking at this...', '2011-06-12 22:57:25.000000', NULL, 1),
(6442234, 955605, 76335, '<td valign="top">Prepared to complain about the possibly overworked textures in the sky, I was interrupted by a cow -- a black one. And I came to my senses.</td>', 'Prepared to complain about the possibly overworked textures in the sky, I was interrupted by a cow -- a black one. And I came to my senses.', '2011-06-12 22:57:27.000000', NULL, 1),
(6442235, 955590, 76335, '<td valign="top">This feels especially minimal for some reason. Like something is missing -- should be there, was there, will come. This really works and I can''t say why.</td>', 'This feels especially minimal for some reason. Like something is missing -- should be there, was there, will come. This really works and I can''t say why.', '2011-06-12 22:57:30.000000', NULL, 1),
(6442236, 955027, 76335, '<td valign="top">Nice gravity, balance in this...</td>', 'Nice gravity, balance in this...', '2011-06-12 22:57:58.000000', NULL, 1),
(6442237, 954861, 76335, '<td valign="top">My kind of Alps!</td>', 'My kind of Alps!', '2011-06-12 22:58:02.000000', NULL, 1),
(6442239, 955643, 76335, '<td valign="top">Starburst tree versus starburst sun. Nice.</td>', 'Starburst tree versus starburst sun. Nice.', '2011-06-12 22:58:07.000000', NULL, 1),
(6442240, 955522, 76335, '<td valign="top">Clouds and cows in pefect harmony.</td>', 'Clouds and cows in pefect harmony.', '2011-06-12 22:58:11.000000', NULL, 1),
(6442245, 955019, 76335, '<td valign="top">I never thought a sky could be too low in the frame without the picture being upside down. This is astounding.</td>', 'I never thought a sky could be too low in the frame without the picture being upside down. This is astounding.', '2011-06-12 22:58:26.000000', NULL, 1),
(6442247, 954936, 76335, '<td valign="top">Garish at first but it grows on you...</td>', 'Garish at first but it grows on you...', '2011-06-12 22:58:45.000000', NULL, 1),
(6442249, 955519, 76335, '<td valign="top">Dazzling brushstrokes (and not much more) define the scene.</td>', 'Dazzling brushstrokes (and not much more) define the scene.', '2011-06-12 22:59:19.000000', NULL, 1),
(6442250, 955406, 76335, '<td valign="top">Charcoal layers -- and a shadowy abode sits in stark relief. Great.</td>', 'Charcoal layers -- and a shadowy abode sits in stark relief. Great.', '2011-06-12 22:59:22.000000', NULL, 1),
(6442251, 955060, 76335, '<td valign="top">Points for something very different. I love the light, the conversion.</td>', 'Points for something very different. I love the light, the conversion.', '2011-06-12 22:59:29.000000', NULL, 1),
(6442253, 955435, 76335, '<td valign="top">Most minimal. Icy and smoky and white all over. Excellent.</td>', 'Most minimal. Icy and smoky and white all over. Excellent.', '2011-06-12 23:00:41.000000', NULL, 1),
(6442262, 955602, 100831, '<td valign="top">gorgeous vista.... love the puffy layers of clouds, the large expanse of sky above and the shadows on the shoreline. Wonderful color too!!</td>', 'gorgeous vista.... love the puffy layers of clouds, the large expanse of sky above and the shadows on the shoreline. Wonderful color too!!', '2011-06-12 23:36:51.000000', NULL, 1),
