(6442267, 955626, 100831, '<td valign="top">Nice details - perfect job with the sharpening. I''m loving the icy processing.</td>', 'Nice details - perfect job with the sharpening. I''m loving the icy processing.', '2011-06-12 23:40:18.000000', NULL, 1),
